INSERT INTO `tb_jalur` (`id_jalur`, `nama_jalur`, `kode_jalur`, `deskripsi`, `persyaratan`, `kuota_persen`, `bobot_rapor`, `bobot_tes`, `is_smk`, `icon`, `warna`, `urutan`, `is_active`, `created_at`) VALUES
(1, 'Jalur Afirmasi', 'afirmasi', 'Jalur khusus untuk siswa dari keluarga kurang mampu yang memiliki bukti kepesertaan program bantuan pemerintah seperti KIP, PKH, atau KIS.', '1. Kartu Indonesia Pintar (KIP) / Kartu Keluarga Sejahtera (KKS)\n2. Surat Keterangan Tidak Mampu (SKTM) dari Kelurahan\n3. Kartu PKH atau KIS yang masih berlaku\n4. Raport semester terakhir\n5. Ijazah/SKL SMP/MTs', 15.00, 30.00, 70.00, 1, 'bi-heart-fill', '#8B5CF6', 1, 1, '2025-12-22 06:53:04'),
(2, 'Jalur Prestasi', 'prestasi', 'Jalur untuk siswa berprestasi di bidang akademik maupun non-akademik dengan sertifikat/piagam kejuaraan minimal tingkat Kota/Kabupaten.', '1. Sertifikat/Piagam Prestasi asli\n2. Minimal prestasi tingkat Kota/Kabupaten\n3. Prestasi 3 tahun terakhir\n4. Raport semester terakhir\n5. Ijazah/SKL SMP/MTs\n6. Surat rekomendasi dari sekolah asal', 25.00, 30.00, 70.00, 1, 'bi-trophy-fill', '#F59E0B', 2, 1, '2025-12-22 06:53:04'),
(3, 'Jalur Zonasi', 'zonasi', 'Jalur berdasarkan jarak domisili ke sekolah tujuan. Prioritas diberikan kepada siswa yang tinggal dalam radius terdekat dari sekolah.', '1. Kartu Keluarga (KK) yang berdomisili di Kota Padang\n2. Minimal domisili 1 tahun sebelum pendaftaran\n3. Bukti kepemilikan/kontrak rumah (jika diperlukan)\n4. Raport semester terakhir\n5. Ijazah/SKL SMP/MTs', 10.00, 30.00, 70.00, 1, 'bi-geo-alt-fill', '#10B981', 3, 1, '2025-12-22 06:53:04'),
(4, 'Jalur Mutasi', 'mutasi', 'Jalur untuk siswa yang orang tuanya pindah tugas karena kedinasan (ASN, TNI, POLRI) atau alasan lain yang dapat dibuktikan.', '1. Surat Keputusan (SK) Pindah Tugas Orang Tua\n2. Surat Keterangan dari instansi terkait\n3. Kartu Keluarga baru\n4. Raport semester terakhir\n5. Ijazah/SKL SMP/MTs\n6. Surat pindah dari sekolah asal', 10.00, 30.00, 70.00, 1, 'bi-arrow-left-right', '#3B82F6', 4, 1, '2025-12-22 06:53:04');
